using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems.", Building = "Turing Hall", Phone = "(555) 100-2000" },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis.", Building = "Euler Center", Phone = "(555) 100-3000" },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and rhetorical studies.", Building = "Whitman Hall", Phone = "(555) 100-4000" },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature.", Building = "Newton Science Center", Phone = "(555) 100-5000" },
            new() { Id = "hist", Name = "History", Description = "World and regional history, historiography, and archival research.", Building = "Heritage Hall", Phone = "(555) 100-6000" },
        ];

        _courses =
        [
            // Computer Science
            new()
            {
                Id = "cs101", Code = "CS 101", Title = "Introduction to Programming",
                Description = "Foundational course covering variables, control flow, functions, and basic data structures using Python. Ideal for students with no prior programming experience.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Turing 201",
                DepartmentId = "cs", Level = "Introductory", IsFeatured = true,
                MaxEnrollment = 120, CurrentEnrollment = 98,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Email = "alovelace@university.edu", Bio = "Dr. Lovelace specializes in programming pedagogy and has published extensively on inclusive introductory curricula. She received her Ph.D. from MIT.", OfficeLocation = "Turing 310" },
                Prerequisites = []
            },
            new()
            {
                Id = "cs201", Code = "CS 201", Title = "Data Structures & Algorithms",
                Description = "In-depth study of arrays, linked lists, trees, graphs, sorting, and searching algorithms. Emphasis on time and space complexity analysis.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Room = "Turing 105",
                DepartmentId = "cs", Level = "Intermediate",
                MaxEnrollment = 80, CurrentEnrollment = 72,
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Professor", Email = "aturing@university.edu", Bio = "Dr. Turing's research focuses on computational complexity and algorithm design. He chairs the department's curriculum committee.", OfficeLocation = "Turing 401" },
                Prerequisites = ["CS 101"]
            },
            new()
            {
                Id = "cs310", Code = "CS 310", Title = "Database Systems",
                Description = "Relational database design, SQL, normalization, indexing strategies, and an introduction to NoSQL systems. Includes a semester-long project building a real-world application.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Turing 110",
                DepartmentId = "cs", Level = "Intermediate", IsFeatured = true,
                MaxEnrollment = 60, CurrentEnrollment = 55,
                Instructor = new() { Name = "Prof. Grace Hopper", Title = "Professor", Email = "ghopper@university.edu", Bio = "Prof. Hopper is a pioneer in database optimization and has consulted for major tech companies. She holds three patents in query processing.", OfficeLocation = "Turing 315" },
                Prerequisites = ["CS 201"]
            },
            new()
            {
                Id = "cs450", Code = "CS 450", Title = "Machine Learning",
                Description = "Survey of supervised and unsupervised learning algorithms, neural networks, and practical applications using modern frameworks.",
                Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", Room = "Turing 220",
                DepartmentId = "cs", Level = "Advanced",
                MaxEnrollment = 40, CurrentEnrollment = 38,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Email = "alovelace@university.edu", Bio = "Dr. Lovelace specializes in programming pedagogy and has published extensively on inclusive introductory curricula. She received her Ph.D. from MIT.", OfficeLocation = "Turing 310" },
                Prerequisites = ["CS 201", "MATH 210"]
            },

            // Mathematics
            new()
            {
                Id = "math101", Code = "MATH 101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Euler 101",
                DepartmentId = "math", Level = "Introductory", IsFeatured = true,
                MaxEnrollment = 150, CurrentEnrollment = 130,
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Email = "enoether@university.edu", Bio = "Dr. Noether is an award-winning educator whose calculus reform textbook is used at over 50 universities.", OfficeLocation = "Euler 205" },
                Prerequisites = []
            },
