@page "/courses"
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-4">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search"
               placeholder="Course name, code, or instructor…" />
    </div>
    <div class="col-md-3">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="department">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <label for="level" class="form-label">Level</label>
        <select class="form-select" id="level" name="level">
            <option value="">All Levels</option>
            @foreach (var lvl in _levels)
            {
                <option value="@lvl" selected="@(Level == lvl)">@lvl</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end gap-2">
        <button type="submit" class="btn btn-primary">Filter</button>
        <a href="courses" class="btn btn-outline-secondary">Clear</a>
    </div>
</form>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-hover align-middle">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Level</th>
                    <th>Instructor</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _courses)
                {
                    var dept = Catalog.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@(dept?.Name ?? course.DepartmentId)</td>
                        <td>@course.Credits</td>
                        <td><span class="badge bg-secondary">@course.Level</span></td>
                        <td>@course.Instructor.Name</td>
                        <td>
                            @if (spotsLeft > 10)
                            {
                                <span class="badge bg-success">@spotsLeft spots</span>
                            }
                            else if (spotsLeft > 0)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots</span>
                            }
                            else
                            {
                                <span class="badge bg-danger">Full</span>
                            }
                        </td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public string? Level { get; set; }

    private List<Course> _courses = [];
    private List<Department> _departments = [];
    private List<string> _levels = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _levels = Catalog.GetLevels();
        _courses = Catalog.GetCourses(Department, Level, Search);
    }
}

@page "/courses/{CourseId}"
@inject CatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-outline-primary">Back to Course List</a>
}
else
{
    <PageTitle>@_course.Code – @_course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item">
                <a href="courses?department=@_course.DepartmentId">@(_department?.Name ?? _course.DepartmentId)</a>
            </li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code – @_course.Title</h1>
            <div class="d-flex gap-2 mb-3">
                <span class="badge bg-primary">@_course.Credits credits</span>
                <span class="badge bg-secondary">@_course.Level</span>
                @{
                    var spotsLeft = _course.MaxEnrollment - _course.CurrentEnrollment;
                }
                @if (spotsLeft > 10)
                {
                    <span class="badge bg-success">@spotsLeft spots available</span>
                }
                else if (spotsLeft > 0)
                {
                    <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                }
                else
                {
                    <span class="badge bg-danger">Full</span>
                }
            </div>

            <section class="mb-4">
                <h4>Description</h4>
                <p>@_course.Description</p>
            </section>

            <section class="mb-4">
                <h4>Schedule & Location</h4>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Schedule</dt>
                    <dd class="col-sm-9">@_course.Schedule</dd>
                    <dt class="col-sm-3">Room</dt>
                    <dd class="col-sm-9">@_course.Room</dd>
                    <dt class="col-sm-3">Department</dt>
                    <dd class="col-sm-9">@(_department?.Name ?? _course.DepartmentId)</dd>
                </dl>
            </section>

            @if (_course.Prerequisites.Count > 0)
            {
                <section class="mb-4">
                    <h4>Prerequisites</h4>
                    <ul class="list-inline">
                        @foreach (var prereq in _course.Prerequisites)
                        {
                            <li class="list-inline-item"><span class="badge bg-outline-dark border">@prereq</span></li>
                        }
                    </ul>
                </section>
            }
        </div>

        <div class="col-lg-4">
            <div class="card mb-4">
                <div class="card-header">
                    <h5 class="mb-0">Instructor</h5>
                </div>
                <div class="card-body">
                    <h6>@_course.Instructor.Name</h6>
                    <p class="text-muted mb-2">@_course.Instructor.Title</p>
                    <p class="mb-2">@_course.Instructor.Bio</p>
                    <dl class="mb-0">
                        <dt>Email</dt>
                        <dd><a href="mailto:@_course.Instructor.Email">@_course.Instructor.Email</a></dd>
                        <dt>Office</dt>
                        <dd>@_course.Instructor.OfficeLocation</dd>
                    </dl>
                </div>
            </div>

            <div class="d-grid">
                <a href="enroll?courseId=@_course.Id" class="btn btn-primary btn-lg">Request Enrollment</a>
                <a href="courses" class="btn btn-outline-secondary mt-2">Back to Course List</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string CourseId { get; set; } = "";

    private Course? _course;
    private Department? _department;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(CourseId);
        if (_course is not null)
        {
            _department = Catalog.GetDepartment(_course.DepartmentId);
        }
    }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted</h4>
        <p>
            Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@(_selectedCourse?.Code) – @(_selectedCourse?.Title)</strong> has been received.
        </p>
        <hr />
        <p class="mb-0">You will receive a confirmation email at your university address. Processing typically takes 1–2 business days.</p>
    </div>
    <a href="enroll" class="btn btn-outline-primary">Submit Another Request</a>
    <a href="courses" class="btn btn-outline-secondary ms-2">Browse Courses</a>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card">
                <div class="card-body">
                    <EditForm Model="_model" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit" Enhance>
                        <DataAnnotationsValidator />
                        <AntiforgeryToken />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                            <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" />
                            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                            <div class="form-text">6–12 alphanumeric characters (e.g., STU123456)</div>
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                                <option value="">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    <option value="@course.Id">@course.Code – @course.Title (@course.Credits cr)</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="comments" class="form-label">Comments (optional)</label>
                            <InputTextArea id="comments" class="form-control" rows="3" @bind-Value="_model.Comments" />
                            <ValidationMessage For="() => _model.Comments" class="text-danger" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </EditForm>
                </div>
            </div>
        </div>
        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5>How it works</h5>
                    <ol class="mb-0">
                        <li>Fill out the form with your details</li>
                        <li>Select the course you wish to enroll in</li>
                        <li>Submit your request</li>
                        <li>The registrar's office will process your request within 1–2 business days</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private List<Course> _courses = [];
    private bool _submitted;
    private Course? _selectedCourse;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(_model.CourseId))
        {
            _model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        _selectedCourse = Catalog.GetCourse(_model.CourseId);
        _submitted = true;
    }
}

